import { getImagesByQuery } from './js/pixabay-api.js';
import { createGallery, clearGallery, showLoader, hideLoader, showLoadMoreButton, hideLoadMoreButton } from './js/render-functions.js';

import iziToast from 'izitoast';
import 'izitoast/dist/css/iziToast.min.css';

let currentPage = 1;
let searchQuery = '';

const form = document.querySelector('.form');
const loadMoreButton = document.querySelector('.load-more-button');

/* FORM */

form.addEventListener('submit', async event => {
    event.preventDefault();
    
    searchQuery = form.elements['search-text'].value.trim();

    if (searchQuery === '') {
        iziToast.error({
            title: 'Error',
            message: 'Please enter search parameters!',
        });
        hideLoader();
        hideLoadMoreButton();
        return;
    }
    
    currentPage = 1;

    clearGallery();
    hideLoadMoreButton();
    showLoader();

    try {
        const data = await getImagesByQuery(searchQuery, currentPage);

        if (!data.hits || data.hits.length === 0) {
            hideLoadMoreButton();
            iziToast.error({
                title: 'Error',
                message: 'Sorry, there are no images matching your search query. Please try again!',
            });
            return;
        } 
        
        createGallery(data.hits);
            
        if (currentPage * 15 < data.totalHits){
            showLoadMoreButton();
        }else{
            hideLoadMoreButton();
                iziToast.info({
                    title: 'info',
                    message: "We're sorry, but you've reached the end of search results.",
                    });
        }
        
    } catch (error) {
        hideLoadMoreButton();
        iziToast.error({
            title: 'Error',
            message: 'An error occurred while fetching images. Please try again later.',
        });
    } finally {
        hideLoader();
    }
});


/*LOAD MORE BUTTON*/

loadMoreButton.addEventListener('click', async () => {
    currentPage++;
    showLoader();

    try {
        const data = await getImagesByQuery(searchQuery, currentPage);
        
        if(!data.hits || data.hits.length === 0){
            hideLoadMoreButton();
            iziToast.info({
                title: 'Info',
                message: "We're sorry, but you've reached the end of search results."
            });
            return;
        }

        createGallery(data.hits);

        const firstImage = document.querySelector('.gallery-image');
        if(firstImage){
            const imageSize = firstImage.getBoundingClientRect().height;
            window.scrollBy(
                {
                    top: imageSize * 2,
                    behavior: "smooth"
                }
            );
        }

        if (currentPage * 15 >= data.totalHits) {
            showLoadMoreButton();
            iziToast.info(
                {
                title: 'Info',
                message: "We're sorry, but you've reached the end of search results.",
            }
        );
        } 
    } catch(error){
        hideLoadMoreButton();
        iziToast.error(
            {
                title: 'error',
                message: "An error occurred while loading more images."
            }
        );
    } finally {
        hideLoader();
    }
});